-- NIH per-model provenance; public educational content only.
-- Existing RLS (world-readable, service-role-only writes) remains in force.
-- Retired mesh IDs remain for account export/history foreign keys.
begin;
alter table public.anatomy_structures add column source jsonb;
alter table public.anatomy_structures add column license jsonb;
alter table public.anatomy_structures add column available boolean not null default true;
alter table public.anatomy_structures alter column source set not null;
alter table public.anatomy_structures alter column license set not null;
alter table public.anatomy_structures add constraint anatomy_provenance_components check (jsonb_typeof(source)='object' and source ? 'geometry' and source ? 'text' and jsonb_typeof(license)='object' and license ? 'geometry' and license ? 'text');
commit;
